import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { ArrowRight, Star, Clock, ChevronRight, Flame } from "lucide-react";
import DishArt from "../components/DishArt";
import { api } from "../api/client";

const currency = (n) => `₹${n.toFixed(0)}`;

export default function Home() {
  const [featured, setFeatured] = useState([]);
  const [error, setError] = useState("");

  useEffect(() => {
    api
      .getMenu()
      .then((items) => setFeatured(items.slice(0, 3)))
      .catch((err) => setError(err.message));
  }, []);

  return (
    <main>
      {/* ---- Signature hero: a dhaba signboard at dusk ---- */}
      <section style={{ background: "var(--night)", position: "relative", overflow: "hidden" }}>
        <StringLights />
        <div
          className="container"
          style={{
            padding: "56px 24px 64px",
            display: "grid",
            gridTemplateColumns: "1.05fr 0.95fr",
            gap: 48,
            alignItems: "center",
            position: "relative",
          }}
        >
          <div style={{ animation: "fadeUp .6s ease" }}>
            <div className="mono" style={{ fontSize: 12, letterSpacing: "0.14em", color: "var(--marigold)", fontWeight: 700, marginBottom: 18 }}>
              EST. ON THE STREET · OPEN TILL LATE
            </div>
            <h1 className="disp" style={{ fontSize: "clamp(40px, 5.2vw, 64px)", lineHeight: 1.02, color: "#FBF1E1", fontWeight: 700, letterSpacing: "-0.02em", margin: 0 }}>
              Real food,
              <br />
              <span style={{ fontStyle: "italic", fontWeight: 500, color: "var(--marigold)" }}>ladled straight</span>
              <br />
              into your dabba.
            </h1>
            <p style={{ fontSize: 17, color: "#D8C9B5", lineHeight: 1.65, marginTop: 20, maxWidth: 440 }}>
              Home-style curries, kathi rolls and shorbas made from produce sourced that
              morning — tracked from our kitchen to your door, no guesswork in between.
            </p>
            <div style={{ display: "flex", gap: 14, marginTop: 32, alignItems: "center", flexWrap: "wrap" }}>
              <Link
                to="/menu"
                className="focus-ring"
                style={{ background: "var(--chili)", color: "#FBF1E1", border: "none", borderRadius: 999, padding: "14px 26px", fontSize: 15, fontWeight: 700, display: "flex", alignItems: "center", gap: 8, boxShadow: "0 10px 24px rgba(198,55,29,0.35)" }}
              >
                Explore the menu <ArrowRight size={16} />
              </Link>
              <div style={{ display: "flex", alignItems: "center", gap: 6, color: "#D8C9B5", fontSize: 14, fontWeight: 600 }}>
                <Star size={15} color="var(--marigold)" fill="var(--marigold)" />
                4.9 · 2,300+ orders this month
              </div>
            </div>
          </div>

          <div style={{ position: "relative", display: "flex", justifyContent: "center" }}>
            <TiffinStack />
            <div
              style={{
                position: "absolute",
                bottom: 4,
                left: 6,
                background: "#FFFCF6",
                borderRadius: 16,
                padding: "12px 16px",
                boxShadow: "0 16px 34px rgba(0,0,0,0.35)",
                display: "flex",
                gap: 10,
                alignItems: "center",
              }}
            >
              <Clock size={18} color="var(--chili)" />
              <div>
                <div style={{ fontSize: 12.5, fontWeight: 700, color: "var(--night)" }}>Avg. 27 min</div>
                <div style={{ fontSize: 11, color: "var(--ink-faint)" }}>kitchen to doorstep</div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* ---- Today's harvest ---- */}
      <section className="container" style={{ padding: "56px 24px 80px" }}>
        <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", marginBottom: 22 }}>
          <div>
            <div className="mono" style={{ fontSize: 11.5, letterSpacing: "0.12em", color: "var(--chili)", fontWeight: 700, marginBottom: 6 }}>
              TODAY'S DABBA
            </div>
            <h2 className="disp" style={{ fontSize: 28, color: "var(--night)", fontWeight: 700, margin: 0 }}>
              Off the tawa, straight to you
            </h2>
          </div>
          <Link to="/menu" className="focus-ring" style={{ color: "var(--chili)", fontWeight: 700, fontSize: 14, display: "flex", gap: 4, alignItems: "center" }}>
            Full menu <ChevronRight size={15} />
          </Link>
        </div>

        {error && (
          <div style={{ background: "#FBEAD8", border: "1px solid rgba(180,85,43,0.3)", color: "var(--rust)", borderRadius: 14, padding: 16, fontSize: 14 }}>
            Couldn't load the menu ({error}). Make sure the backend API is running and seeded.
          </div>
        )}

        {!error && (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 18 }}>
            {featured.map((item, idx) => (
              <div key={item._id} style={{ background: "#FFFCF6", borderRadius: 20, padding: 18, border: "1px solid var(--border)" }}>
                <DishArt seed={idx} />
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 12 }}>
                  {item.tags?.[0] && (
                    <span style={{ fontSize: 11, fontWeight: 800, color: "var(--marigold)", letterSpacing: "0.04em" }}>
                      {item.tags[0].toUpperCase()}
                    </span>
                  )}
                  <span style={{ fontSize: 11, color: "var(--ink-faint)", display: "flex", alignItems: "center", gap: 3 }}>
                    <Flame size={11} /> {item.calories} kcal
                  </span>
                </div>
                <div className="disp" style={{ fontSize: 17, fontWeight: 600, color: "var(--night)", marginTop: 4 }}>
                  {item.name}
                </div>
                <div style={{ fontSize: 13.5, color: "var(--ink-faint)", marginTop: 4 }}>{item.description}</div>
                <div className="mono" style={{ marginTop: 12, fontWeight: 700, color: "var(--chili)", fontSize: 15 }}>{currency(item.price)}</div>
              </div>
            ))}
          </div>
        )}
      </section>
    </main>
  );
}

/** Row of glowing bulbs along the hero's top edge — the "signboard at dusk" signature. */
function StringLights() {
  const bulbs = Array.from({ length: 22 });
  return (
    <svg viewBox="0 0 1180 34" preserveAspectRatio="none" style={{ width: "100%", height: 34, display: "block" }}>
      <path d="M0 4 Q 590 34 1180 4" stroke="#4A3320" strokeWidth="2" fill="none" />
      {bulbs.map((_, i) => {
        const t = i / (bulbs.length - 1);
        const x = 10 + t * 1160;
        const y = 4 + Math.sin(t * Math.PI) * 30;
        const delay = (i % 5) * 0.4;
        return (
          <circle key={i} cx={x} cy={y} r={4} fill="var(--marigold)" style={{ animation: `glow 2.4s ease-in-out ${delay}s infinite` }} />
        );
      })}
    </svg>
  );
}

/** A stacked tiffin carrier (dabba) — the signature dish illustration. */
function TiffinStack() {
  const tiers = [
    { fill: "var(--chili)" },
    { fill: "var(--marigold)" },
    { fill: "var(--curry)" },
  ];
  return (
    <svg viewBox="0 0 300 380" style={{ width: "100%", maxWidth: 300 }}>
      {/* steam */}
      <path d="M120 60 Q128 40 120 22" stroke="#FBF1E1" strokeWidth="4" fill="none" strokeLinecap="round" opacity="0.35" />
      <path d="M150 54 Q158 32 150 12" stroke="#FBF1E1" strokeWidth="4" fill="none" strokeLinecap="round" opacity="0.3" />
      <path d="M180 60 Q188 40 180 22" stroke="#FBF1E1" strokeWidth="4" fill="none" strokeLinecap="round" opacity="0.35" />

      {/* handle */}
      <path d="M115 78 Q150 40 185 78" stroke="#D8C9B5" strokeWidth="7" fill="none" strokeLinecap="round" />
      <rect x="140" y="70" width="20" height="14" rx="4" fill="#D8C9B5" />

      {/* tiers */}
      {tiers.map((t, i) => {
        const y = 90 + i * 90;
        return (
          <g key={i}>
            <rect x="60" y={y} width="180" height="82" rx="16" fill={t.fill} />
            <rect x="60" y={y} width="180" height="14" rx="7" fill="#FBF1E1" opacity="0.22" />
            <rect x="52" y={y + 68} width="196" height="16" rx="8" fill="#D8C9B5" opacity="0.9" />
          </g>
        );
      })}

      {/* base */}
      <ellipse cx="150" cy="360" rx="110" ry="16" fill="#000000" opacity="0.18" />
    </svg>
  );
}
